// One KYB file in, one decision out: approve, review or stop.
// Every rule reads a documented field of GET /v1/kyb/{siren}.
// Reading rules served by the API: https://api.sirenic.eu/v1/lecture
// A file is approved only when every block these rules read was served and
// read in full: a missing or unavailable block is never read as nothing to
// report, so the file goes to a human.
const kyb = $json.body;
const reasons = [];

// A company that has ceased trading cannot open an account.
const status = kyb.identite?.etat_administratif;
const ceased = Boolean(status) && status !== 'actif';
if (ceased) reasons.push(`company ceased (Sirene status: ${status})`);
if (!status) reasons.push('administrative status unknown');

// Insolvency history from the BODACC: it counts only when it was read in full.
// When the BODACC is down, the block says "indisponible", with neither
// coverage nor list of proceedings.
const bodacc = kyb.alertes_bodacc ?? {};
const historyRead = bodacc.couverture?.procedures_collectives_completes === true && Array.isArray(bodacc.procedures_collectives);
if (!historyRead) {
  reasons.push(bodacc.couverture?.procedures_collectives_completes === false
    ? 'insolvency history not fully read'
    : `insolvency history not read (BODACC block: ${bodacc.statut ?? 'no coverage served'})`);
}

// Insolvency proceedings: a human reads the latest judgment, because a
// recovery plan keeps the company trading. Some notices are filings, not
// judgments (a statement of debts): the latest JUDGMENT wins.
const proceedings = Array.isArray(bodacc.procedures_collectives) ? bodacc.procedures_collectives : [];
if (proceedings.length > 0) {
  const judgments = proceedings.filter((notice) => /^jugement/i.test(notice.jugement?.nature ?? ''));
  const dated = (notice) => String(notice.jugement?.date ?? notice.date_parution ?? '');
  const latest = [...(judgments.length > 0 ? judgments : proceedings)].sort((a, b) => dated(b).localeCompare(dated(a)))[0];
  reasons.push(`${proceedings.length} insolvency notice(s), latest judgment: ${latest.jugement?.nature ?? 'unknown'} (${dated(latest)})`);
}

// Officers: served by the registry, then each one screened (below).
const officersServed = Array.isArray(kyb.identite?.dirigeants) && kyb.identite.dirigeants.length > 0;
if (!officersServed) reasons.push('officers not served (missing block: dirigeants)');

// Sanctions: a match is a name match to verify, never a decision.
// rapprochements_partiels_seulement counts in no verdict (API reading rule);
// any other status goes to a human.
const screening = kyb.criblage_sanctions ?? {};
const screeningClear = ['aucune_correspondance', 'rapprochements_partiels_seulement'].includes(screening.statut);
if (screening.statut === 'correspondances_a_verifier') {
  const targets = (screening.cibles ?? [])
    .filter((target) => (target.correspondances ?? []).length > 0)
    .map((target) => `${target.cible} (${target.role === 'dirigeant' ? 'officer' : 'company'})`);
  reasons.push(`sanctions matches to verify: ${targets.join(', ')}`);
} else if (screening.statut === 'aucune_correspondance_partielle') {
  reasons.push(`screening incomplete, lists unavailable: ${(screening.listes_absentes ?? []).join(', ')}`);
} else if (!screeningClear) {
  reasons.push(`sanctions screening not conclusive (status: ${screening.statut ?? 'not served'})`);
}
const unscreened = screening.cibles_non_criblees;
const allScreened = Array.isArray(unscreened) && unscreened.length === 0;
if (!Array.isArray(unscreened)) reasons.push('screening of every officer not confirmed (cibles_non_criblees not served)');
else if (unscreened.length > 0) reasons.push(`${unscreened.length} officer(s) not screened`);

// Blocks not read, or read only in part: the review message names them.
const screeningRead = ['aucune_correspondance', 'rapprochements_partiels_seulement', 'correspondances_a_verifier'].includes(screening.statut) && allScreened;
const notRead = new Set((kyb.blocs_manquants ?? []).map((block) => block.bloc));
if (!status) notRead.add('identite');
if (!historyRead) notRead.add('alertes_bodacc');
if (!officersServed) notRead.add('dirigeants');
if (!screeningRead) notRead.add('criblage_sanctions');

// Approve only a complete, clean file: everything else goes to a human.
const complete = status === 'actif' && historyRead && proceedings.length === 0 && officersServed && screeningClear && allScreened;

return {
  json: {
    checkedAt: new Date().toISOString(),
    siren: kyb.siren,
    company: kyb.identite?.denomination ?? '',
    decision: ceased ? 'stop' : complete ? 'approve' : 'review',
    reasons: reasons.join('; '),
    screening: screening.statut ?? '',
    completeness: kyb.score_completude ?? '',
    missingBlocks: (kyb.blocs_manquants ?? []).map((block) => block.bloc).join(', '),
    notRead: [...notRead].join(', '),
  },
};

